#include <vector>
#include <iostream>

int main() {
    std::vector<int> v;
    v.reserve(100); // Pre-allocate storage

    int& ref = v.emplace_back(10);
    std::cout << "Initial Capacity: " << v.capacity() << "\n";

    // If we insert enough elements to trigger reallocation
    // the reference 'ref' becomes invalid.
    for (int i = 0; i < 100; ++i) {
        v.push_back(i);
    }

    // If v.capacity() was less than 101, reallocation occurred.
    // std::cout << ref; // DANGER: UB if reallocation happened

    std::cout << "Final Capacity: " << v.capacity() << "\n";
}
